static class Track extends FilterOutputStream {
    boolean closed, flushed;
    Track(OutputStream o) { super(o); }
    @Override public void flush() throws IOException { flushed = true; super.flush(); }
    @Override public void close() throws IOException { closed = true; super.close(); }
}

Track inner = new Track(new FileOutputStream("f5.txt"));
try (OutputStream out = new BufferedOutputStream(inner)) {   // 바깥만 try 에 둔다
    out.write("안녕".getBytes("UTF-8"));
}
// 안쪽 close() 가 불렸나 = true
// 안쪽 flush() 가 불렸나 = true

